          Q('时间序列平稳性通常指：', ['均值和方差不随时间变化', '序列必须单调', '没有季节项', '样本量足够大'], 0, '严平稳要求联合分布不随时间平移变化，弱平稳关注均值、方差与自协方差。'),
          Q('PrefixSpan 用于挖掘：', ['频繁项集', '序列模式', '聚类中心', '异常点'], 1, 'PrefixSpan 基于前缀投影挖掘频繁子序列，保留时间顺序。')
