          Q('解释 p 值时正确说法是：', ['原假设为真的概率', '原假设成立时出现当前或更极端结果的概率', '备择假设为真的概率', '置信水平'], 1, 'p 值是在原假设下由数据计算的条件概率。'),
          Q('类别不平衡时不宜只看：', ['召回率', '准确率', 'F1', 'PR 曲线'], 1, '多数类会主导准确率，少数类指标更能反映模型价值。')
